const path = location.pathname;
const concept = path.includes('build-your-way-out') ? 'journey' : path.includes('business-school') ? 'school' : 'operator';
const photos = {hero:'/assets/academy-apartment.webp',one:'/assets/apartment-living.webp',two:'/assets/apartment-dining.webp',three:'/assets/apartment-windows.webp'};
const labels = {launch:'Join the free webinar',scale:'Book a free strategy call',checklist:'Get the free checklist'};
const btn = (type='launch',secondary=false) => `<button class="button ${secondary?'secondary':''}" data-flow="${type}"><span>${labels[type]}</span><span class="arrow" aria-hidden="true">↗</span></button>`;
const picture = (src,alt,cls='',eager=false) => `<img class="${cls}" src="${src}" alt="${alt}" width="1536" height="1024" ${src===photos.hero?'srcset="/assets/academy-apartment-small.webp 768w, /assets/academy-apartment.webp 1536w" sizes="(max-width: 767px) 100vw, 1536px"':''} ${eager?'fetchpriority="high" loading="eager"':'loading="lazy"'} decoding="async">`;
const nav = `<header class="main-nav wrap"><a class="logo" href="${path}">flex<span>academy</span><i>®</i></a><nav aria-label="Main navigation"><a href="#story">Our story</a><a href="#programmes">Programmes</a><a href="#method">The approach</a></nav>${btn()}</header>`;
const brands = [{name:'The Flex',title:'We built the business.',body:'Furnished apartments across international markets. Real guests, real properties and the daily work of running a hospitality company.',tag:'The operating company'}, {name:'Base360',title:'We built the systems.',body:'Property management software created to run The Flex. The same operating systems now support other STR businesses.',tag:'The operating system'}, {name:'Flex Academy',title:'Now build yours.',body:'The playbooks, coaching and operator support to help you start your first units or build your portfolio into a company.',tag:'Your next chapter'}];
function ecosystem(){return `<section id="story" class="ecosystem wrap"><div class="section-heading"><h2>${concept==='school'?'A school with an operating history.':concept==='journey'?'Ambition, backed by experience.':'The experience behind the playbook.'}</h2><p>One business became an operating system. Both became the foundation for Flex Academy.</p></div><div class="ecosystem-layout">${concept==='operator'?`<figure class="ecosystem-photo">${picture(photos.two,'Illustrative furnished rental apartment with a warm, considered interior')}<figcaption>Built around the realities of hospitality.</figcaption></figure>`:''}<div class="ecosystem-items">${brands.map((b,i)=>`<article>${concept==='journey'&&i===0?picture(photos.two,'Illustrative hospitality apartment, representing the operating business','ecosystem-bento-image'):''}<div class="brand-name">${b.name}</div><div><h3>${b.title}</h3><p>${b.body}</p></div></article>`).join('')}</div></div></section>`}
const offers = {launch:{name:'Launch',title:'Your first units. Your own business.',description:'For people with zero or one unit who want to start with a clear plan, practical tools and experienced support.',features:['Self-paced, practical course','Live group sessions with operators','Templates, checklists and launch playbooks','Community and ongoing support'],outcome:'Find opportunities. Evaluate the numbers. Launch your first units with a plan.',meta:'Programme price: X'},scale:{name:'Scale',title:'From portfolio to company.',description:'Turn a portfolio that depends on you into an operation with systems, clearer margins and room to grow.',features:['Weekly group sessions over 12 weeks','Monthly 1:1 with a founder','SOPs and operating systems','Operator community and Base360 access'],outcome:'Less manual work. More operational clarity. An operation equipped for its next stage.',meta:'12-week programme · Programme price: Y'}};
function offer(type){const o=offers[type];return `<article class="programme ${type}"><div class="programme-heading"><span class="programme-name">${o.name}</span><h3>${o.title}</h3><p>${o.description}</p></div><div class="offer-content"><ul>${o.features.map(f=>`<li>${f}</li>`).join('')}</ul><p class="outcome">${o.outcome}</p>${btn(type,type==='scale')}<small>${o.meta}</small></div></article>`}
function programmes(){return `<section id="programmes" class="programmes wrap"><div class="section-heading"><span class="eyebrow">YOUR STARTING POINT</span><h2>${concept==='school'?'Two paths. A shared standard.':concept==='journey'?'Start small. Build something real.':'Choose your next move.'}</h2></div><div class="programme-layout">${offer('launch')}${offer('scale')}</div></section>`}
const steps=[{title:'Understand the opportunity.',body:'Assess a market, evaluate a property and work through the numbers before committing.',name:'Opportunity'},{title:'Build the operation.',body:'Turn guest experience, pricing, cleaning and daily workflows into repeatable processes.',name:'Operations'},{title:'Grow with intention.',body:'Review performance, refine your systems and make informed decisions about the next unit.',name:'Growth'}];
function method(){return `<section id="method" class="method"><div class="wrap"><div class="section-heading"><h2>${concept==='school'?'The business, from every angle.':'Learn it. Apply it. Build on it.'}</h2><p>A practical approach that connects the knowledge to the work.</p></div><div class="method-layout"><div class="method-items">${steps.map((s,i)=>`<article><span class="method-label">${s.name}</span><div><h3>${s.title}</h3><p>${s.body}</p></div></article>`).join('')}</div>${concept==='journey'?`<figure>${picture(photos.one,'Illustrative apartment interior showing a living area and balcony')}</figure>`:''}</div></div></section>`}
function founders(){return `<section class="founders wrap"><div class="founder-copy"><span class="eyebrow">FROM THE FOUNDERS</span><h2>We built it. Then built the systems behind it.</h2><p>Flex Academy grew out of the work of building The Flex and Base360. Every property brought decisions about guests, people, pricing and processes.</p><p>Now that operating knowledge becomes your path forward, with education, coaching and a community that understands the work.</p><a href="#story" class="text-link">Explore the ecosystem <span aria-hidden="true">↗</span></a></div><figure>${picture(photos.three,'Illustrative contemporary apartment, representing the hospitality business')}<figcaption>From running properties to teaching the business.</figcaption></figure></section>`}
const proof = `<section class="proof wrap"><h2>Real work.<br>Shared experience.</h2><div class="quote"><blockquote>“Understand the numbers. Build the process. Make your next decision with clarity.”</blockquote><p>Illustrative testimonial. An approved member story will appear here.</p></div></section>`;
const checklist = `<section class="checklist wrap"><div class="checklist-heading"><h2>Ready for your<br>next unit?</h2><p>The free STR Scaling Checklist. Review the numbers, processes and people behind your next stage.</p>${btn('checklist')}</div><div class="checklist-topics" aria-label="Checklist topics"><p>Financial clarity<span>Know your unit economics.</span></p><p>Repeatable operations<span>Build processes that hold.</span></p><p>People & systems<span>Create capacity to grow.</span></p></div></section>`;
const final = `<section class="final wrap"><h2>Build something<br>you can call yours.</h2><div><p>Start with the free webinar.<br>Get a clearer picture of the work ahead.</p><div class="actions">${btn()}${btn('scale',true)}</div></div></section>`;
const footer = `<footer class="wrap"><div class="footer-top"><a class="logo" href="/operator/">flex<span>academy</span></a><p>Built from experience.<br>Built for what’s next.</p><nav aria-label="Footer navigation"><a href="#programmes">Programmes</a><a href="#story">Our story</a><button data-flow="checklist">${labels.checklist}</button></nav></div><div class="footer-bottom"><small>© ${new Date().getFullYear()} Flex Academy</small><small>Concept preview. Forms demonstrate the journey; no registrations are sent.</small></div><details class="credits"><summary>About the concept imagery</summary><p>AI-generated apartment photography is illustrative. Additional photography: <a href="https://www.domino.com/design-inspiration/grand-army-plaza-apartment-tour-salle/">Domino</a>, <a href="https://www.plumguide.com/homes/1251419/tottenham-sanctuary">Plum Guide</a> and <a href="https://bloom-zollikon.ch/">Bloom Zollikon</a>. These images do not depict The Flex properties.</p></details></footer>`;
const heroes = {
operator:`<section class="operator-hero wrap"><div class="hero-layout"><div><span class="eyebrow">BUILT BY OPERATORS. FOR OPERATORS.</span><h1>Build a real<br>STR business.</h1></div><div class="hero-support"><p>Launch or scale with the playbooks and people who built The Flex and Base360.</p><div class="actions">${btn()}${btn('scale',true)}</div></div></div><figure class="operator-panorama">${picture(photos.hero,'Illustrative sunlit apartment, created for the Flex Academy design concept','',true)}</figure></section>`,
journey:`<section class="journey-hero wrap"><div class="journey-content"><span class="eyebrow">YOUR NEXT CHAPTER</span><h1>Build an income<br>you own.</h1><p>Learn to launch a real short-term rental business, one considered step at a time.</p><div class="actions">${btn()}${btn('scale',true)}</div></div><figure class="journey-hero-photo">${picture(photos.hero,'Illustrative sunlit apartment with natural materials and thoughtful furnishings','',true)}</figure></section>`,
school:`<section class="school-hero wrap"><div class="school-copy"><span class="eyebrow">THE STR BUSINESS SCHOOL</span><h1>The business<br>behind the stay.</h1><p>From your first unit to a multi-market operation, learn the systems behind The Flex and Base360.</p><div class="actions">${btn()}${btn('scale',true)}</div></div><figure>${picture(photos.hero,'Illustrative editorial photograph of a furnished hospitality apartment','',true)}</figure></section>`
};
const stages=`<section class="journey-stages wrap"><h2>You don’t need a portfolio.<br>You need a starting point.</h2><ol>${[{name:'Your 9-to-5',body:'Start with the time you have.'},{name:'First property',body:'Find and evaluate an opportunity.'},{name:'First systems',body:'Make the daily work repeatable.'},{name:'First portfolio',body:'Grow from a stronger foundation.'},{name:'Your STR company',body:'Build the operation behind it.'}].map(s=>`<li><h3>${s.name}</h3><p>${s.body}</p></li>`).join('')}</ol><p class="stage-note">No overnight promises. A practical path to a business of your own.</p></section>`;
const schoolNote=`<section class="school-editorial wrap"><h2>A short-term rental is a property.<br>A great operation is a business.</h2><p>See the whole picture: the opportunity, the economics, the guest experience and the systems that hold it all together.</p></section>`;
document.body.classList.add(concept);
document.querySelectorAll('.concept-bar a').forEach(a=>a.classList.toggle('active',a.pathname===path || (path==='/'&&a.pathname==='/operator/')));
document.getElementById('app').innerHTML = nav + '<main>' + heroes[concept] + (concept==='journey'?stages:concept==='school'?schoolNote:'') + ecosystem() + programmes() + method() + founders() + proof + checklist + final + '</main>' + footer;
document.title = {operator:'Flex Academy | Built by operators',journey:'Flex Academy | Build an income you own',school:'Flex Academy | The STR Business School'}[concept];
// The theme control is preview-only and deliberately does not persist visitor data.
const themeButton=document.getElementById('theme');
const media=matchMedia('(prefers-color-scheme: dark)');
function setTheme(theme){document.documentElement.dataset.theme=theme;themeButton.textContent=theme==='dark'?'Light mode':'Dark mode';themeButton.setAttribute('aria-label',`Switch to ${theme==='dark'?'light':'dark'} mode`)}
setTheme(media.matches?'dark':'light');themeButton.addEventListener('click',()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));
media.addEventListener('change',e=>setTheme(e.matches?'dark':'light'));
if(concept!=='school'&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}},{threshold:.08});document.querySelectorAll('.section-heading,.ecosystem-items article,.programme,.method-items article,.founder-copy,.quote,.checklist-heading').forEach(el=>{el.classList.add('reveal');observer.observe(el)});}
const dialog=document.getElementById('flow'),content=document.getElementById('flow-content');dialog.setAttribute('aria-label','Flex Academy conversion preview');let flowType,selectedSlot;const sampleDate='2026-10-15';
function field(label,name,type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" required ${extra}></label>`}
function openFlow(type){flowType=type;selectedSlot=null;content.innerHTML=type==='launch'?`<span class="eyebrow">FREE INTRODUCTORY WEBINAR</span><h2>Your first unit.<br>A clearer plan.</h2><p>Explore what it takes to launch an STR business.<br>Preview date: 15 October 2026 · 18:00 São Paulo (UTC−3).</p><form>${field('Name','name')}${field('Email','email','email')}${field('Country','country')}<button class="button">Register for the free webinar ↗</button></form>`:type==='scale'?`<span class="eyebrow">FREE STRATEGY CALL / STEP 1 OF 2</span><h2>Tell us where<br>you’re building.</h2><form>${field('Units today','units','number','min="0"')}${field('Target number of units','target','number','min="1"')}${field('City / market','market')}<label>Budget band<select name="budget" required><option value="">Choose a band</option><option>Under $5,000</option><option>$5,000-$15,000</option><option>$15,000-$50,000</option><option>$50,000+</option></select></label><button class="button">Choose a time ↗</button></form>`:`<span class="eyebrow">FREE STR SCALING CHECKLIST</span><h2>Make your next<br>step a clear one.</h2><p>A practical checklist for evaluating your operation.</p><form>${field('Name','name')}${field('Email','email','email')}<button class="button">Get the checklist ↓</button></form>`;content.insertAdjacentHTML('beforeend','<small class="preview-note">Interactive concept preview. No personal data is stored or sent.</small>');if (!dialog.open) dialog.showModal();}
document.addEventListener('click',e=>{const target=e.target.closest('[data-flow]');if(target)openFlow(target.dataset.flow);if(e.target.closest('.close'))e.target.closest('dialog').close()});document.getElementById('compare').onclick=()=>document.getElementById('comparison').showModal();
content.addEventListener('submit',e=>{e.preventDefault();if(flowType==='launch'){content.innerHTML=`<span class="eyebrow">REGISTRATION PREVIEW COMPLETE</span><h2>You’re in.</h2><p>Webinar: Your first STR business<br>15 October 2026 · 18:00-19:00 São Paulo (UTC−3)</p><p>This is a sample confirmation. A live registration service will be connected before launch.</p><button class="button" id="calendar">Add to Calendar ↓</button>`;document.getElementById('calendar').onclick=()=>download('flex-webinar.ics','BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Flex Academy//Concept//EN\r\nBEGIN:VEVENT\r\nUID:flex-preview-20261015\r\nDTSTAMP:20261002T210000Z\r\nDTSTART:20261015T210000Z\r\nDTEND:20261015T220000Z\r\nSUMMARY:Flex Academy webinar (concept preview)\r\nDESCRIPTION:Sample event only. Not a confirmed live webinar.\r\nEND:VEVENT\r\nEND:VCALENDAR','text/calendar');}else if(flowType==='scale'){content.innerHTML=`<span class="eyebrow">STRATEGY CALL / STEP 2 OF 2</span><h2>Make time for<br>your next stage.</h2><p>Preview availability · São Paulo time (UTC−3)</p><form><label>Date<select name="date" required><option>16 October 2026</option><option>19 October 2026</option><option>20 October 2026</option></select></label><fieldset><legend>Choose a time</legend>${['10:00','14:00','16:30'].map(t=>`<label class="slot"><input type="radio" name="time" value="${t}" required> ${t}</label>`).join('')}</fieldset><button class="button">Confirm preview booking ↗</button></form>`;flowType='booking';}else if(flowType==='booking'){const data=new FormData(e.target);content.innerHTML=`<span class="eyebrow">BOOKING PREVIEW COMPLETE</span><h2>Your strategy<br>call is booked.</h2><p>${data.get('date')} · ${data.get('time')} São Paulo (UTC−3)<br>30-minute call</p><p>This demonstrates the confirmation state. No appointment has been created. Live availability and booking will be connected before launch.</p>`;}else{const checklist='FLEX ACADEMY : STR SCALING CHECKLIST\n\nFINANCIAL CLARITY\n[ ] Know your net margin for every unit.\n[ ] Include rent, cleaning, utilities, platform fees and maintenance.\n[ ] Set an operating reserve.\n\nREPEATABLE OPERATIONS\n[ ] Document check-in and guest communication.\n[ ] Define cleaning standards and escalation steps.\n[ ] Track maintenance and recurring tasks.\n\nPEOPLE AND SYSTEMS\n[ ] Assign responsibility for every workflow.\n[ ] Track tasks in a shared operating system.\n[ ] Test whether operations can run without you for a day.\n\nYOUR NEXT UNIT\n[ ] Evaluate market demand and local requirements.\n[ ] Model realistic revenue and downside scenarios.\n[ ] Check that your team and systems can support growth.\n';download('flex-academy-scaling-checklist.txt',checklist,'text/plain');content.innerHTML='<span class="eyebrow">YOUR CHECKLIST IS READY</span><h2>A clearer view.<br>A better next step.</h2><p>Your checklist download has started. Review your margins, processes and team before adding the next unit.</p><button class="button" data-flow="scale">Book a free strategy call ↗</button>';}});
function download(name,text,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
